//   英語の時だけ i18n.js から読む（日本語の時は読まない・重さ0）。クラウド29 11/21。
//   拾い方：?lang=en で戦を一つ勝ちで終え、各画面を開いて日本語のまま残る字を数えた（scratch enflow2.mjs）。
//   戦ごとの話（任務の名・城下の出来事の台詞・史実と後日談）は各戦の表の受け持ち。ここは全戦で同じ画面の字と、数の入る形だけ。
import AFTER from './i18n_after.js';
import ODA_TOWN from './i18n_oda_town.js';
import LORE from './i18n_lore.js';   // 戦の由来と心得（screens.js の LORE・次の戦の心得）   // 織田家編の城下の中身（oda_town.js）   // 史実と後日談（after_history.js）
const KD = { 一: 1, 二: 2, 三: 3, 四: 4, 五: 5, 六: 6, 七: 7, 八: 8, 九: 9 };
const kanN = (t) => { if (/^\d+$/.test(t)) return +t; let n = 0, d = 0; for (const c of t) { if (KD[c]) d = KD[c]; else if (c === '十') { n += (d || 1) * 10; d = 0; } else if (c === '百') { n += (d || 1) * 100; d = 0; } else return NaN; } return n + d; };
const NUM = '[一二三四五六七八九十百\\d]+';
// 「六貫」「4貫800文」「0文」→ "6 kan" "4 kan 800 mon" "0 mon"
const money = (s) => {
  const m = String(s).trim().match(new RegExp(`^(?:(${NUM})貫)?(?:(${NUM})文)?$`));
  if (!m || (!m[1] && !m[2])) return undefined;
  const k = m[1] ? kanN(m[1]) : 0, mo = m[2] ? kanN(m[2]) : 0;
  if (Number.isNaN(k) || Number.isNaN(mo)) return undefined;
  return [k ? `${k} kan` : '', mo || !k ? `${mo} mon` : ''].filter(Boolean).join(' ');
};
const MONEY = `(?:${NUM}貫)?(?:${NUM}文)?`;
const RANK = { 雑兵: 'Foot soldier', 足軽: 'Ashigaru', 足軽大将: 'Ashigaru captain', 侍大将: 'Samurai commander', 武将: 'Warlord', 大名: 'Daimyo' };
const GRADE = { 甲上: 'A+', 甲: 'A', 乙: 'B', 丙: 'C', 丁: 'D' };
const GRADE_WORD = { 上々: 'excellent', よし: 'good', まずまず: 'fair', 働き不足: 'not enough work', 足りぬ: 'not enough' };
const REL = { 尊敬: 'Respect', 警戒: 'Wariness', 信頼: 'Trust', 好感: 'Liking', 上官の評価: 'Superior\'s rating' };
const KANDAN = { 一: 1, 二: 2, 三: 3, 四: 4, 五: 5, 六: 6 };
const minus = (s) => s.replace(/[−－]/g, '-').replace(/＋/g, '+');
const enOr = (t, s) => { const e = t(s); return /[぀-ヿ㐀-鿿]/.test(e) ? undefined : e; };

